@Serializable
sealed interface Command

@Serializable @SerialName("render")
data class RenderCommand(val reportId: Int) : Command

fun invoke(envelope: String, json: Json) {
    val cmd = json.decodeFromString<Command>(envelope)   // reads classDiscriminator
    when (cmd) {                                         // adding a case breaks the build
        is RenderCommand -> renderer.render(cmd.reportId)
    }
}
